package com.sakib.portebo.util;
import java.text.SimpleDateFormat;import java.util.Calendar;import java.util.Date;import java.util.Locale;import java.util.TimeZone;
public final class BengaliDateFormat{private static final String[] MONTHS={"জানুয়ারি","ফেব্রুয়ারি","মার্চ","এপ্রিল","মে","জুন","জুলাই","আগস্ট","সেপ্টেম্বর","অক্টোবর","নভেম্বর","ডিসেম্বর"};private BengaliDateFormat(){}public static String format(String raw){Date d=parse(raw);if(d==null)return "সময় জানা যায়নি";Calendar c=Calendar.getInstance();c.setTime(d);int h=c.get(Calendar.HOUR);if(h==0)h=12;String out=String.format(Locale.US,"%02d %s %04d, %02d:%02d %s",c.get(Calendar.DAY_OF_MONTH),MONTHS[c.get(Calendar.MONTH)],c.get(Calendar.YEAR),h,c.get(Calendar.MINUTE),c.get(Calendar.AM_PM)==Calendar.AM?"AM":"PM");return bengaliDigits(out);}private static Date parse(String v){if(v==null||v.trim().isEmpty())return null;try{long n=Long.parseLong(v);if(v.length()>=12)return new Date(n);}catch(Exception ignored){}String[] patterns={"yyyy-MM-dd'T'HH:mm:ss.SSS'Z'","yyyy-MM-dd'T'HH:mm:ss'Z'","yyyy-MM-dd'T'HH:mm:ss.SSSXXX","yyyy-MM-dd'T'HH:mm:ssXXX","yyyy-MM-dd HH:mm"};for(String p:patterns){try{SimpleDateFormat f=new SimpleDateFormat(p,Locale.US);f.setLenient(false);if(p.endsWith("'Z'"))f.setTimeZone(TimeZone.getTimeZone("UTC"));Date d=f.parse(v);if(d!=null)return d;}catch(Exception ignored){}}return null;}public static String formatTime(int hour,int minute){int h=hour%12;if(h==0)h=12;return bengaliDigits(String.format(Locale.US,"%d:%02d",h,minute));}public static String toBengaliDigits(String s){return bengaliDigits(s);}public static String formatDateOnly(long millis){Calendar c=Calendar.getInstance();c.setTimeInMillis(millis);String s=String.format(Locale.US,"%02d %s %04d",c.get(Calendar.DAY_OF_MONTH),MONTHS[c.get(Calendar.MONTH)],c.get(Calendar.YEAR));return bengaliDigits(s);}private static String bengaliDigits(String s){StringBuilder b=new StringBuilder(s.length());for(int i=0;i<s.length();i++){char c=s.charAt(i);b.append(c>='0'&&c<='9'?(char)('০'+c-'0'):c);}return b.toString();}}
